import React from "react";
import "./adpage.css";

const AdPage = () => {
  return (
    <div className="adpage-container">
      {/* Banner Section */}
      <div className="banner">
        <img
          src="https://m.media-amazon.com/images/I/71nwqPZaNRL._SX3000_.jpg"
          alt="Main Ad"
        />
      </div>

      {/* Card Rows */}
      <div className="card-section">
        <h2>Recommended Products</h2>
        <div className="card-row">
          {Array.from({ length: 4 }).map((_, i) => (
            <div className="card" key={i}>
              <img src={`https://source.unsplash.com/200x200/?product,${i}`} alt="Product" />
              <h4>Product {i + 1}</h4>
              <p>Brand Name</p>
            </div>
          ))}
        </div>

        <h2>Top Brands</h2>
        <div className="card-row">
          {Array.from({ length: 4 }).map((_, i) => (
            <div className="card" key={i}>
              <img src={`https://source.unsplash.com/200x200/?brand,${i}`} alt="Brand" />
              <h4>Brand {i + 1}</h4>
              <p>Explore Now</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default AdPage;
